calculation.formula:
//countd(if datediff('quarter',[Load Date],today())=1 then [Model ID] end)

countd(
if ([LoadDate]=dateadd('day', -1, DATETRUNC('quarter', TODAY()))) and [Overall_Model_Performance] in ('Degraded','Unsatisfactory') and [model_Status]='Active' and [Country (ArcherModelPerformance)]='United States' then [Model ID] end

)

countd( 
if [Overall_Model_Performance (ArcherModelPerformance)] = 'Degraded' and [Country (ArcherModelPerformance)]='United States' and [model_Status (ArcherModelPerformance)]='Active'  then [Model ID (ArcherModelPerformance)] end
)

//countd(if datediff('quarter',[Load Date],today())=1 then [Model ID] end)

count(
if ([LoadDate]=dateadd('day', -1, DATETRUNC('quarter', TODAY()))) and [model_Status] = 'Degraded'  and [Country]='United States' and [model_Status]='Active'   then [Model ID] end

)

//countd(if datediff('quarter',[Load Date],today())=1 then [Model ID] end)

countd(
if ([LoadDate]=dateadd('day', -1, DATETRUNC('quarter', TODAY()))) and [Overall_Model_Performance] = 'Unsatisfactory' then [Model ID] end

)

