IF CONTAINS([Model URL], 'https:')
THEN 'Click here  ' ELSE '' END

//IF [Sort Order] = 'Asc' THEN
CASE [Parameters].[Parameter 3]
    WHEN "Model Name" THEN [Model Name]
    WHEN "Model Owner" THEN [Model Owner (MO)]
    when  'Business Unit' then [Model_Business_Unit]
    //WHEN "Model Type" THEN [Model Type]
    when 'Model Science Domain' then [Analytics Department (group)]
    WHEN "Model Version Status" THEN [Current Version Status]
    WHEN "Model Risk Tier" THEN [Final Model Tier Rating]
   WHEN "Model Surveillance Lead" THEN [Model Surveillance Lead]
   when "Model Surveillance Implementation Status" then [Model_Surveillance_Implementation_Status] 
   //when "Model Surveillance Implementation Date" then [Model Surveillance Implementation Date] 
   //when 'Type of Surveillance Used ' then [Type of Surveillance Used ]  
WHEN "Model Surveillance Platform" THEN [Calculation_1121267945734144]

//when 'Surveillance Not Pass Reason' then [Surveillance Not Pass Reason ]

   
END

